    async def update_error_group_resolution(
        self,
        fingerprint: str,
        *,
        status: ErrorResolutionStatus,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> ErrorGroupResolution:
        """
        Sets an error group's triage state to `resolved`, `ignored` or `unresolved`. The state is saved per organization and fingerprint, and List error groups returns it as `resolution`.

        Parameters
        ----------
        fingerprint : str
            Error group fingerprint from List error groups: 16 uppercase hex characters, case-sensitive.

        status : ErrorResolutionStatus
            `resolved`, `ignored`, or `unresolved` to reopen.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        ErrorGroupResolution
            The saved state.

        Examples
        --------
        import asyncio

        from respan import AsyncRespanClient

        client = AsyncRespanClient(
            authorization="YOUR_AUTHORIZATION",
            respan_api_key="YOUR_RESPAN_API_KEY",
        )


        async def main() -> None:
            await client.error_groups.update_error_group_resolution(
                fingerprint="9F3B2C1D4E5A6B7C",
                status="resolved",
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.update_error_group_resolution(
            fingerprint, status=status, request_options=request_options
        )
        return _response.data
